import pytest
from isort._vendored.tomli._parser import Flags

class TestFlags:

    @pytest.fixture
    def flags_instance(self):
        return Flags()  # Initialize your Flags instance as needed

    def test_is_empty_key(self, flags_instance):
        """Test with an empty key, should return False."""
        result = flags_instance.is_([], 1)
        assert result is False

    def test_is_no_flags(self, flags_instance):
        """Test with a key that has no flags defined."""
        flags_instance._flags = {}
        result = flags_instance.is_(["nonexistent"], 1)
        assert result is False

    def test_is_key_not_in_cont(self, flags_instance):
        """Test with a key that is not present in the flags."""
        flags_instance._flags = {"key_1": {"nested": {}}}
        result = flags_instance.is_(["nonexistent_key"], 1)
        assert result is False

    def test_is_recursive_flag_true(self, flags_instance):
        """Test where a key exists and flag is in recursive_flags."""
        flags_instance._flags = {
            "key_1": {
                "recursive_flags": [1],
                "nested": {}
            }
        }
        result = flags_instance.is_(["key_1"], 1)
        assert result is True

    def test_is_recursive_flag_false(self, flags_instance):
        """Test where a key exists and flag is not in recursive_flags."""
        flags_instance._flags = {
            "key_1": {
                "recursive_flags": [2],
                "nested": {}
            }
        }
        result = flags_instance.is_(["key_1"], 1)
        assert result is False

    def test_is_flag_in_inner_keys(self, flags_instance):
        """Test with a key that leads to nested flags."""
        flags_instance._flags = {
            "key_1": {
                "recursive_flags": [],
                "nested": {
                    "key_2": {
                        "flags": [1],
                        "recursive_flags": []
                    }
                }
            }
        }
        result = flags_instance.is_(["key_1", "key_2"], 1)
        assert result is True

    def test_is_key_stem_not_in_cont(self, flags_instance):
        """Test with last key stem not present."""
        flags_instance._flags = {
            "key_1": {
                "nested": {}
            }
        }
        result = flags_instance.is_(["key_1", "key_2"], 1)
        assert result is False

import pytest
from isort.format import format_simplified

def test_format_simplified_from_import():
    assert format_simplified("from module import function") == "module.function"

def test_format_simplified_import():
    assert format_simplified("import module") == "module"

def test_format_simplified_empty():
    assert format_simplified("") == ""

def test_format_simplified_no_import():
    assert format_simplified("module.function") == "module.function"

def test_format_simplified_whitespace():
    assert format_simplified("   import   module   \n") == "module"

def test_format_simplified_from_import_with_whitespace():
    assert format_simplified("   from   module   import   function  ") == "module.function"

def test_format_simplified_invalid_format():
    assert format_simplified("random_string") == "random_string"
